(function (root) {
  'use strict';
  const M = root.CampusModel;
  function render(s, query, h) {
    const { e, icon, fmt, badge, button, taskBadge, empty, proofBlock, history } = h;
    const tab = query.get('tab') || 'appeals';
    const queue = s.submissions.filter(x => x.status === 'appealed' || x.challenge?.status === 'pending');
    const check = M.assertState(s);
    let body = '';
    if (tab === 'appeals') body = `<div class="callout info">目标在 3 个工作日内处理。所有裁决必须填写理由，双方均可见；奖励回滚时答题者可用积分不足，会拦截并保留待办，不产生负余额。</div>${queue.length ? queue.map(x => {
      const t = M.task(s, x.taskId), at = x.challenge?.status === 'pending' ? x.challenge.at : x.appealedAt;
      return `<article class="task-row"><div class="row-head"><h3>${e(t.title)}</h3>${badge(x.challenge?.status === 'pending' ? '自动通过争议' : x.appealKind === 'first-review' ? '首份证明复核' : '拒绝申诉', 'warning')}</div><p>发布者：${e(M.user(s, t.publisherId).nickname)}，答题者：${e(M.user(s, x.userId).nickname)}</p><p>申请时间 ${fmt(at)}；已等待 ${Math.floor((s.now - at) / M.HOUR)} 小时${s.now - at > 3 * M.DAY ? '，请优先处理（已超过 3 个自然日）' : ''}</p>${proofBlock(x)}<div class="callout">${e(x.challenge?.status === 'pending' ? x.challenge.reason : x.appealReason)}</div>${history(x)}<div class="actions">${button('查看并作出裁决', 'judge', `data-id="${e(x.id)}"`, '')}</div></article>`;
    }).join('') : empty('当前没有待处理申诉', '这里会显示拒绝申诉、首份证明复核和自动通过争议。上方可切换任务管理、用户管理或数据看板。', 'admin?tab=tasks', '查看全部任务')}`;
    else if (tab === 'tasks') {
      const status = query.get('status') || '';
      const rows = s.tasks.filter(t => !status || t.status === status).slice().reverse();
      body = `<div class="filters"><label for="admin-status">任务状态</label><select id="admin-status" name="adminStatus"><option value="">全部状态</option>${[['open', '招募中'], ['settling', '待结算'], ['closed', '已结束'], ['removed', '已下架']].map(([value, label]) => `<option value="${value}" ${value === status ? 'selected' : ''}>${label}</option>`).join('')}</select></div>${rows.map(t => `<article class="task-row"><div class="row-head"><h3><a href="#detail/${e(t.id)}">${e(t.title)}</a></h3>${taskBadge(t)}</div><p>发布者 ${e(M.user(s, t.publisherId).nickname)}，已收 ${M.approved(s, t)} / ${t.quota}，保留预算 ${M.fmtPoints(t.escrow)} 分</p><p>截止 ${fmt(t.deadline)}，链接报告 ${t.reports.length} 次</p>${t.removalReason ? `<p>下架原因：${e(t.removalReason)}</p>` : ''}<div class="actions">${t.status !== 'removed' ? button('强制下架', 'admin-remove', `data-id="${e(t.id)}"`, 'danger') : ''}${['open', 'settling'].includes(t.status) && !t.stopped ? button('延长截止时间', 'admin-extend', `data-id="${e(t.id)}"`) : ''}<a class="text-button" href="#review/${e(t.id)}">查看提交记录</a></div></article>`).join('') || empty('这个状态下没有任务', '换一个状态查看。', 'admin?tab=tasks', '查看全部任务')}`;
    } else if (tab === 'users') {
      const users = s.users.slice().sort((a, b) => +M.publisherRisk(s, b.id).high - +M.publisherRisk(s, a.id).high);
      body = `<p class="small muted">高风险规则：拒绝率大于 50% 且拒绝数至少 3。命中后待审核及后续证明自动通过。</p>${users.map(u => {
        const risk = M.publisherRisk(s, u.id);
        return `<article class="task-row"><div class="row-head"><h3>${e(u.nickname)}${u.sample ? '（示例同学）' : ''}</h3>${badge(u.banned ? '已封禁' : risk.high ? '高风险发布者' : u.restrictedUntil > s.now ? '限制发布中' : '正常', u.banned ? 'error' : risk.high ? 'warning' : '')}</div><p>可用 ${M.fmtPoints(u.available)} 分，冻结 ${M.fmtPoints(u.frozen)} 分，发布 ${s.tasks.filter(t => t.publisherId === u.id).length} 次，完成 ${s.submissions.filter(x => x.userId === u.id && x.status === 'approved').length} 份</p><p>拒绝率 ${Math.round(risk.rate * 100)}%（${risk.rejected}/${risk.reviewed}），违规 ${u.violations} 次；注册 ${fmt(u.createdAt)}</p>${u.role !== 'admin' ? `<div class="actions">${button('管理权限与积分', 'admin-user', `data-id="${e(u.id)}"`)}</div>` : ''}</article>`;
      }).join('')}<h2>管理员操作留痕</h2>${s.audit.slice().reverse().map(a => `<p class="small muted">${fmt(a.at)} ${e(M.user(s, a.userId).nickname)}：${e(a.operation)}，${e(a.reason)}</p>`).join('') || '<p class="small muted">暂无用户管理操作。</p>'}`;
    } else if (tab === 'metrics') {
      const submitted = s.submissions.filter(x => x.submittedAt), approved = submitted.filter(x => x.status === 'approved'), rejected = submitted.filter(x => x.history.some(h => h.action === '拒绝')), appeals = submitted.filter(x => x.history.some(h => h.action === '申诉')), reviewed = submitted.filter(x => x.history.some(h => ['通过', '拒绝', '管理员裁决'].includes(h.action))), completed = s.tasks.filter(t => t.status === 'closed' && M.approved(s, t) > 0).length;
      const mean = reviewed.length ? reviewed.reduce((sum, x) => sum + Math.max(0, (x.history.find(h => ['通过', '拒绝', '管理员裁决'].includes(h.action))?.at || x.resolvedAt) - x.submittedAt), 0) / reviewed.length / M.HOUR : null;
      const rate = (n, d) => d ? Math.round(n / d * 100) + '%' : '暂无样本';
      const data = [['注册 / 7 日活跃', `${s.users.length} / ${s.users.filter(u => u.lastActiveAt >= s.now - 7 * M.DAY).length}`, '示例账户纳入统计'], ['发布 / 已闭环', `${s.tasks.length} / ${completed}`, `闭环率 ${rate(completed, s.tasks.length)}；结束且至少通过一份`], ['平均首次审核', mean === null ? '暂无样本' : mean.toFixed(1) + ' 小时', '从提交到首次处理'], ['拒绝率 / 申诉率', `${rate(rejected.length, reviewed.length)} / ${rate(appeals.length, submitted.length)}`, '拒绝按首次处理，申诉按已提交记录'], ['系统积分 / 应有总量', `${M.fmtPoints(check.total)} / ${M.fmtPoints(check.expected)}`, '所有可用 + 冻结 = 启动积分 + 调账净额'], ['领取未提交', rate(s.submissions.filter(x => !x.submittedAt).length, s.submissions.length), '含等待提交、超时释放及取消'], ['发布后无人领取', rate(s.tasks.filter(t => !s.submissions.some(x => x.taskId === t.id)).length, s.tasks.length), '用于定位冷启动卡点']];
      body = `<div class="callout">积分守恒校验通过。以下全部由当前演示记录计算，不代表真实用户运营数据。</div><dl class="stats-grid">${data.map(([label, value, note]) => `<div class="stat ${label.includes('系统积分') ? 'stat-healthy' : label.includes('拒绝率') || label.includes('领取未提交') ? 'stat-attention' : ''}"><dt>${label}</dt><dd class="number">${e(value)}</dd><small>${note}</small></div>`).join('')}</dl><div class="panel"><h3>先验证三个问题</h3><ol><li>20 人一周内是否至少完成 5 个任务闭环？</li><li>审核纠纷率是否低于 20%，且没有人因此退出？</li><li>新用户能否在 30 秒内理解“答题赚积分，再发问卷”？</li></ol><p class="small muted">真实访谈与试用需由团队组织；此处仅提供观察框架，不伪造验证结果。</p></div>`;
    } else body = empty('没有这个管理页面', '请选择上方管理功能。', 'admin', '回申诉队列');
    return `<div class="admin-workspace"><div class="page-heading"><div><h1>管理员工作台</h1><p>让每一次互助，都有一个公平的结果。</p></div>${badge('模拟管理员', 'info')}</div><div class="time-bar"><span>${icon('clock')} 演示时间：${fmt(s.now)}（相对现实前移 ${s.timeOffset / M.HOUR} 小时）</span>${button('推进时间', 'time')}</div><nav class="tabs admin-tabs" aria-label="管理员四个管理模块">${[['appeals', '申诉队列' + (queue.length ? `（${queue.length}）` : '')], ['tasks', '任务管理'], ['users', '用户管理'], ['metrics', '数据看板']].map(([value, text]) => `<a href="#admin?tab=${value}" ${tab === value ? 'aria-current="page"' : ''}>${text}</a>`).join('')}</nav><p class="admin-caption small muted">申诉裁决、任务下架、权限与积分管理、运行数据，都在这里处理。当前为本地演示，不涉及真实账户。</p>${body}</div>`;
  }
  function judgeModal(s, id, h) {
    const x = M.sub(s, id), challenge = x.challenge?.status === 'pending';
    h.modal('作出管理员裁决', h.dialogForm('judge', id, `<label class="field"><span>裁决结果</span><select name="verdict" required><option value="">选择裁决结果</option>${(challenge ? [['dismiss', '维持通过，不回滚'], ['reverse', '认定恶意提交，回滚奖励']] : [['win', '判答题者胜，发放奖励'], ['uphold', '维持拒绝，释放保留名额'], ['remove', '双方无责，下架任务并释放本记录']]).map(([value, label]) => `<option value="${value}">${label}</option>`).join('')}</select></label>${h.reasonField('请写出依据，答题者和发布者都能看到。')}`, '确认裁决'));
  }
  function userModal(s, id, h) {
    h.modal('管理' + M.user(s, id).nickname, h.dialogForm('manageUser', id, `<label class="field"><span>管理操作</span><select name="operation"><option value="restrict">限制发布</option><option value="ban">封禁账号</option><option value="restore">解除封禁和发布限制</option><option value="flag">记录一次违规</option><option value="adjust">积分调账</option></select></label><label class="field"><span>限制天数（限制发布时生效）</span><input type="number" name="days" min="1" max="30" value="7"></label><label class="field"><span>调账积分（可保留一位小数，正数增加，负数扣除）</span><input type="number" name="amount" value="0" min="-10000" max="10000" step="0.1" inputmode="decimal"></label>${h.reasonField('说明依据，此操作将保留管理员记录。')}`, '确认管理操作'));
  }
  root.CampusAdmin = { render, judgeModal, userModal };
})(globalThis);
